                                                                'concern that '
                                                                'uncontrolled '
                                                                'reactivity could '
                                                                'alkylate off-target '
                                                                'cysteines and drive '
                                                                'idiosyncratic '
                                                                'toxicity. Which '
                                                                'statement best '
                                                                'captures the design '
                                                                'constraints and risk? '
                                                                'Targeted covalent '
                                                                'design needs precise '
                                                                'noncovalent docking '
                                                                'plus tempered '
                                                                'electrophilicity; '
                                                                'hyper-reactive '
                                                                'warheads increase '
                                                                'off-target protein '
                                                                'adduct risk. PROTACs '
                                                                'act via event-driven '
                                                                'E3 recruitment and '
                                                                'proteasomal '
                                                                'degradation and can '
                                                                'turn over '
                                                                'catalytically, but '
